import{a as e,i as t,r as n,t as r}from"./app-Dkwa1Gla.js";var i=JSON.parse(`{"path":"/%E7%AC%AC07%E7%AB%A0%20%E9%A1%B9%E7%9B%AE%E7%AB%8B%E9%A1%B9%E7%AE%A1%E7%90%86/7.3%20%E6%8B%9B%E6%8A%95%E6%A0%87%E7%AE%A1%E7%90%86.html","title":"7.3 招投标管理","lang":"zh-CN","frontmatter":{},"git":{},"filePathRelative":"第07章 项目立项管理/7.3 招投标管理.md"}`),a={name:`7.3 招投标管理.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="_7-3-招投标管理" tabindex="-1"><a class="header-anchor" href="#_7-3-招投标管理"><span>7.3 招投标管理</span></a></h1><h2 id="定义" tabindex="-1"><a class="header-anchor" href="#定义"><span>定义</span></a></h2><p>招投标管理是指通过招标方式选择项目承包商或供应商的过程，确保公平、公正、公开地选择合作伙伴。</p><h2 id="招投标流程" tabindex="-1"><a class="header-anchor" href="#招投标流程"><span>招投标流程</span></a></h2><h3 id="_1-招标公告" tabindex="-1"><a class="header-anchor" href="#_1-招标公告"><span>1. 招标公告</span></a></h3><ul><li><strong>内容</strong>：项目概况、投标人资格要求、投标截止日期</li><li><strong>发布渠道</strong>：官方网站、行业媒体</li></ul><h3 id="_2-资格预审" tabindex="-1"><a class="header-anchor" href="#_2-资格预审"><span>2. 资格预审</span></a></h3><ul><li><strong>内容</strong>：审查投标人资格</li><li><strong>要点</strong>：资质、业绩、财务状况</li></ul><h3 id="_3-招标文件编制" tabindex="-1"><a class="header-anchor" href="#_3-招标文件编制"><span>3. 招标文件编制</span></a></h3><ul><li><strong>内容</strong>：招标须知、技术要求、合同条款、评标方法</li><li><strong>作用</strong>：指导投标人编制投标文件</li></ul><h3 id="_4-投标文件编制" tabindex="-1"><a class="header-anchor" href="#_4-投标文件编制"><span>4. 投标文件编制</span></a></h3><ul><li><strong>内容</strong>：商务部分、技术部分、报价部分</li><li><strong>要求</strong>：响应招标文件要求</li></ul><h3 id="_5-开标" tabindex="-1"><a class="header-anchor" href="#_5-开标"><span>5. 开标</span></a></h3><ul><li><strong>内容</strong>：公开宣读投标文件</li><li><strong>要求</strong>：投标人代表在场监督</li></ul><h3 id="_6-评标" tabindex="-1"><a class="header-anchor" href="#_6-评标"><span>6. 评标</span></a></h3><ul><li><strong>内容</strong>：评审投标文件</li><li><strong>方法</strong>：综合评估法、最低评标价法</li></ul><h3 id="_7-中标通知" tabindex="-1"><a class="header-anchor" href="#_7-中标通知"><span>7. 中标通知</span></a></h3><ul><li><strong>内容</strong>：通知中标结果</li><li><strong>要求</strong>：在规定时间内发出</li></ul><h3 id="_8-合同签订" tabindex="-1"><a class="header-anchor" href="#_8-合同签订"><span>8. 合同签订</span></a></h3><ul><li><strong>内容</strong>：签订正式合同</li><li><strong>要求</strong>：明确双方权利义务</li></ul><h2 id="评标方法" tabindex="-1"><a class="header-anchor" href="#评标方法"><span>评标方法</span></a></h2><h3 id="综合评估法" tabindex="-1"><a class="header-anchor" href="#综合评估法"><span>综合评估法</span></a></h3><ul><li><strong>特点</strong>：综合考虑技术、商务、报价等因素</li><li><strong>适用</strong>：技术复杂的项目</li></ul><h3 id="最低评标价法" tabindex="-1"><a class="header-anchor" href="#最低评标价法"><span>最低评标价法</span></a></h3><ul><li><strong>特点</strong>：以价格为主要评审因素</li><li><strong>适用</strong>：技术简单的项目</li></ul><h3 id="经评审的最低投标价法" tabindex="-1"><a class="header-anchor" href="#经评审的最低投标价法"><span>经评审的最低投标价法</span></a></h3><ul><li><strong>特点</strong>：在满足技术要求的前提下，选择最低报价</li><li><strong>适用</strong>：标准化程度高的项目</li></ul><h2 id="招投标管理的原则" tabindex="-1"><a class="header-anchor" href="#招投标管理的原则"><span>招投标管理的原则</span></a></h2><h3 id="公开原则" tabindex="-1"><a class="header-anchor" href="#公开原则"><span>公开原则</span></a></h3><ul><li>招标信息公开</li><li>评标过程公开</li></ul><h3 id="公平原则" tabindex="-1"><a class="header-anchor" href="#公平原则"><span>公平原则</span></a></h3><ul><li>所有投标人平等竞争</li><li>不得歧视任何投标人</li></ul><h3 id="公正原则" tabindex="-1"><a class="header-anchor" href="#公正原则"><span>公正原则</span></a></h3><ul><li>评标标准公正</li><li>评审过程公正</li></ul><h3 id="诚实信用原则" tabindex="-1"><a class="header-anchor" href="#诚实信用原则"><span>诚实信用原则</span></a></h3><ul><li>投标人应诚实守信</li><li>不得弄虚作假</li></ul><h2 id="关键考点" tabindex="-1"><a class="header-anchor" href="#关键考点"><span>关键考点</span></a></h2><ol><li><strong>招投标流程</strong></li><li><strong>评标方法</strong></li><li><strong>招投标管理原则</strong></li></ol><h2 id="记忆口诀" tabindex="-1"><a class="header-anchor" href="#记忆口诀"><span>记忆口诀</span></a></h2><p>公告预审投标开标评标中标签约，招投标流程要记牢</p><h2 id="典型例题" tabindex="-1"><a class="header-anchor" href="#典型例题"><span>典型例题</span></a></h2><p><strong>例题</strong>：以下哪种评标方法适用于技术复杂的项目？ A. 最低评标价法 B. 综合评估法 C. 经评审的最低投标价法 D. 抽签法</p><p><strong>答案</strong>：B</p><p><strong>解析</strong>：综合评估法综合考虑技术、商务、报价等因素，适用于技术复杂的项目。最低评标价法适用于技术简单的项目，经评审的最低投标价法适用于标准化程度高的项目。</p>`,44)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};